std::vector<PolygonWithHoles2d> result;
try {
    CGAL::Polygon_2<Kernel> p1, p2;
    for (const auto& pt : P1.outerBoundary()) {
        p1.push_back(pt);
    }
    for (const auto& pt : P2.outerBoundary()) {
        p2.push_back(pt);
    }

    std::list<CGAL::Polygon_with_holes_2<Kernel>> diff;
    CGAL::difference(p1, p2, std::back_inserter(diff));

    for (const auto& poly_with_holes : diff) {
        PolygonWithHoles2d resultPoly;
        resultPoly.outerBoundary() = std::vector<Point2d>(poly_with_holes.outer_boundary().vertices_begin(), poly_with_holes.outer_boundary().vertices_end());
        for (auto it = poly_with_holes.holes_begin(); it != poly_with_holes.holes_end(); ++it) {
            resultPoly.holes().push_back(std::vector<Point2d>(it->vertices_begin(), it->vertices_end()));
        }
        result.push_back(resultPoly);
    }
} catch (...) {
    // Handle any CGAL exceptions by returning empty result
}
return result;

